class A { x: number; s: string; b: boolean; }
class B extends A { y: number[]; }
function main(): void {
  const a = new A();
  console.log(a.x, a.s, a.b, typeof a.x, a.x === undefined);
  console.log(a);
  const b = new B();
  console.log(b);
  a.x = 3; a.s = "q";
  console.log(a, a.x + 1);
  console.log(JSON.stringify(new A()));
}
